import{_ as e,o as p,c as s,a2 as a}from"./chunks/framework.BXzK3EA4.js";const o="/assets/image-ubuntu240801.CMRvF4GE.png",l="/assets/image-ubuntu240802.-Bc6WUj1.png",n="/assets/image-ubuntu240803.BGlfStiq.png",u="/assets/image-ubuntu240804.eZ5hn6pN.png",r="/assets/image-ubuntu240805.Dpls2RFb.png",b=JSON.parse('{"title":"Ubuntu18.04-22.04防火墙开/关和修改远程端口","description":"","frontmatter":{"title":"Ubuntu18.04-22.04防火墙开/关和修改远程端口"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/linux/ubuntu-firewall-and-remote-port.md","filePath":"ops-knowledge-base/operating-system/linux/ubuntu-firewall-and-remote-port.md","lastUpdated":1788259091000}'),i={name:"ops-knowledge-base/operating-system/linux/ubuntu-firewall-and-remote-port.md"};function c(m,t,_,d,w,f){return p(),s("div",null,[...t[0]||(t[0]=[a('<p>Ubuntu18.04-22.04，系统默认防火墙是ufw （Uncomplicated Firewall）以Ubuntu18.04为例 ,如下图所示：</p><p><img src="'+o+'" alt=""></p><p>1.看防火墙状态,默认是关闭的 #ufw status</p><p><img src="'+l+'" alt=""></p><p>2.开启防火墙 #ufw enable</p><p><img src="'+n+'" alt=""></p><p>3.关闭防火墙</p><p>#Ufw disable</p><p><img src="'+u+'" alt=""></p><p>4.如防火墙开启，放行指定端口命令如下</p><p>ufw allow 80/tcp ##放行端口80 ufw allow 22/tcp ##放行端口22 ufw allow 8112/tcp ##放行端口8112 ufw allow 1000:2000/tcp ##放行端口范围 1000 到 2000</p><p>5.删除放行端口命令如下</p><p>ufw delete allow 80/tcp ##删除放行端口80 ufw delete allow 22/tcp ##删除放行端口22 ufw delete allow 1000:2000/tcp ##删除放行端口范围1000:2000</p><p>6.修改远程端口，重启ssh服务，并放行新的远程端口</p><p>例如当前机器远程端口为22，需要修改远程端口为2882，示例命令如下： sed -i &#39;s/^Port 22/Port 2882/&#39; /etc/ssh/sshd_config ##修改远程端口 systemctl restart sshd ##重启ssh服务器 ufw allow 2882/tcp ##放行新的远程端口</p><p><img src="'+r+'" alt=""></p><p>7.使用新端口进行远程登录</p><p>ssh root@具体IP -p 2882</p><p>(以上操作同样适用debian10-12系统)</p>',19)])])}const h=e(i,[["render",c]]);export{b as __pageData,h as default};
